/// 这一行为什么显示不出原文。
enum ReplyRowReason {
  none,

  /// 服务端没下发，按「已删除」占位。
  deleted,

  /// 被本地过滤规则删掉，按「已屏蔽」占位。
  blocked,
}

/// 一行的内容从哪来。
enum ReplyRowSource {
  /// 传进去的那一页，按 [`ReplyThreadRow::index`] 取。
  data,

  /// 被过滤规则删掉、从 `removed` 里捞回来的，按 [`ReplyThreadRow::id`] 取。
  removed,

  /// 合成出来的占位，整条在 [`ReplyThreadRow::placeholder`] 里。
  synthetic,
}

