/// 正文里的一段。宿主按 [`Self::kind`] 建对应的 `InlineSpan`。
class ReplySegment {
  final ReplySegmentKind kind;

  /// 要画出来的文本。表情段是占位符原文。
  final String text;

  /// Mention 段：被 @ 的 mid。
  final PlatformInt64? mid;

  /// Topic 段：不带 `#` 的话题名。
  final String? topic;

  /// Emote 段：表情本身。
  final ReplyEmote? emote;

  /// Vote 段：投票 id 与标题。
  final ReplyVote? vote;

  /// Timestamp 段：要跳到的秒数。`None` = 超出稿件时长或解析不出来，
  /// 此时只当纯文本画（不变色、不可点）。
  final PlatformInt64? seekSeconds;

  /// Link 段：标题前的小图标。
  final String? prefixIcon;
  final ReplyTapAction action;

  /// [`Self::action`] 的载荷。
  final String target;

  const ReplySegment({
    required this.kind,
    required this.text,
    this.mid,
    this.topic,
    this.emote,
    this.vote,
    this.seekSeconds,
    this.prefixIcon,
    required this.action,
    required this.target,
  });

  @override
  int get hashCode =>
      kind.hashCode ^
      text.hashCode ^
      mid.hashCode ^
      topic.hashCode ^
      emote.hashCode ^
      vote.hashCode ^
      seekSeconds.hashCode ^
      prefixIcon.hashCode ^
      action.hashCode ^
      target.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ReplySegment &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          text == other.text &&
          mid == other.mid &&
          topic == other.topic &&
          emote == other.emote &&
          vote == other.vote &&
          seekSeconds == other.seekSeconds &&
          prefixIcon == other.prefixIcon &&
          action == other.action &&
          target == other.target;
}

/// 一段正文是什么。镜像 [`richtext::ReplySegmentKind`]。
enum ReplySegmentKind {
  text,
  emote,
  mention,
  topic,
  vote,
  timestamp,
  link,
  note,
}

