/// 点下去干什么。载荷统一放 [`ReplySegment::target`]。
enum ReplyTapAction {
  /// 不可点，界面按次要色画。
  none,

  /// 内置 webview 打开 `target`。
  webview,

  /// 稿件页。`target` 是 av/bv 字面量。
  archive,

  /// 专栏。`target` 是 cvid。
  article,

  /// 图文动态。`target` 是 opus id。
  opus,

  /// app scheme 路由。`target` 是服务端给的跳转串。
  scheme,

  /// 搜索结果页。`target` 是关键词。
  search,
}

