/// DFS 前序里的一行。
///
/// **不带实体**（合成出来的占位除外）：宿主删评论时按 `identical` 在原始
/// 列表里定位，把实体重新发一遍回去会让那个判定失效。见
/// `bili_domain::reply_thread` 的模块文档。
class ReplyThreadRow {
  final ReplyRowSource source;

  /// `Data`：传进去那一页的下标。
  final int? index;

  /// `Removed` / `Synthetic`：评论 id。
  final PlatformInt64 id;

  /// `Synthetic`：合成出来的占位。
  final ReplyEntity? placeholder;

  /// 0 是根评论的直接子节点。
  final int depth;

  /// 父**行**的下标；`None` 表示挂在根评论下。
  final int? parent;
  final ReplyRowReason reason;

  /// 这一行被自动折叠起来的后代数量。0 表示没折叠。
  final int collapsed;

  /// 这一刻画不画得出来。折叠节点的整棵子树为 false。
  final bool visible;

  const ReplyThreadRow({
    required this.source,
    this.index,
    required this.id,
    this.placeholder,
    required this.depth,
    this.parent,
    required this.reason,
    required this.collapsed,
    required this.visible,
  });

  @override
  int get hashCode =>
      source.hashCode ^
      index.hashCode ^
      id.hashCode ^
      placeholder.hashCode ^
      depth.hashCode ^
      parent.hashCode ^
      reason.hashCode ^
      collapsed.hashCode ^
      visible.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ReplyThreadRow &&
          runtimeType == other.runtimeType &&
          source == other.source &&
          index == other.index &&
          id == other.id &&
          placeholder == other.placeholder &&
          depth == other.depth &&
          parent == other.parent &&
          reason == other.reason &&
          collapsed == other.collapsed &&
          visible == other.visible;
}

